begin;
create type public.store_generation_status as enum('queued','running','completed','failed');
create type public.store_status as enum('draft','generated','approved','published');
create type public.store_section_type as enum('hero','featured_product','benefits','product_details','trust','testimonials','faq','newsletter','footer');
create type public.store_page_type as enum('home','product','about','contact','faq','shipping','returns','privacy','terms');
alter table public.brand_directions add constraint brand_directions_store_identity_unique unique(id,selected_product_id,business_id,organization_id);
create table public.store_generation_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,business_id uuid not null,approved_brand_id uuid not null,selected_product_id uuid not null,status public.store_generation_status not null default'queued',provider text not null check(provider in('openai','mock')),model text not null check(char_length(model)between 1 and 100),preferences jsonb not null default'{}'::jsonb check(jsonb_typeof(preferences)='object'),error text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,constraint store_runs_business_fk foreign key(business_id,organization_id)references public.businesses(id,organization_id)on delete cascade,constraint store_runs_brand_fk foreign key(approved_brand_id,selected_product_id,business_id,organization_id)references public.brand_directions(id,selected_product_id,business_id,organization_id)on delete restrict,constraint store_runs_identity_unique unique(id,approved_brand_id,selected_product_id,business_id,organization_id));
create table public.stores(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,business_id uuid not null,approved_brand_id uuid not null,selected_product_id uuid not null,generation_run_id uuid not null,name text not null check(char_length(name)between 2 and 120),slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),status public.store_status not null default'draft',theme jsonb not null check(jsonb_typeof(theme)='object'),navigation jsonb not null check(jsonb_typeof(navigation)='array'),footer jsonb not null check(jsonb_typeof(footer)='object'),seo_defaults jsonb not null check(jsonb_typeof(seo_defaults)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),approved_at timestamptz,constraint stores_business_fk foreign key(business_id,organization_id)references public.businesses(id,organization_id)on delete cascade,constraint stores_run_fk foreign key(generation_run_id,approved_brand_id,selected_product_id,business_id,organization_id)references public.store_generation_runs(id,approved_brand_id,selected_product_id,business_id,organization_id)on delete cascade,constraint stores_identity_unique unique(id,business_id,organization_id));
create table public.store_sections(id uuid primary key default gen_random_uuid(),organization_id uuid not null,business_id uuid not null,store_id uuid not null,section_type public.store_section_type not null,position integer not null check(position between 0 and 100),content jsonb not null check(jsonb_typeof(content)='object'),settings jsonb not null default'{}'::jsonb check(jsonb_typeof(settings)='object'),is_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint store_sections_store_fk foreign key(store_id,business_id,organization_id)references public.stores(id,business_id,organization_id)on delete cascade,constraint store_sections_position_unique unique(store_id,position)deferrable initially immediate,unique(store_id,section_type));
create table public.store_pages(id uuid primary key default gen_random_uuid(),organization_id uuid not null,business_id uuid not null,store_id uuid not null,page_type public.store_page_type not null,slug text not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),title text not null check(char_length(title)between 2 and 200),seo_title text not null check(char_length(seo_title)between 2 and 160),seo_description text not null check(char_length(seo_description)between 2 and 320),content jsonb not null check(jsonb_typeof(content)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint store_pages_store_fk foreign key(store_id,business_id,organization_id)references public.stores(id,business_id,organization_id)on delete cascade,unique(store_id,page_type),unique(store_id,slug));
create unique index store_runs_one_active_per_business on public.store_generation_runs(business_id)where status in('queued','running');
create unique index stores_one_per_business on public.stores(business_id);
create index store_runs_tenant on public.store_generation_runs(organization_id,business_id,created_at desc);create index stores_tenant on public.stores(organization_id,business_id);create index store_sections_order on public.store_sections(store_id,position);create index store_pages_lookup on public.store_pages(store_id,page_type);
create trigger stores_updated before update on public.stores for each row execute function public.set_updated_at();create trigger store_sections_updated before update on public.store_sections for each row execute function public.set_updated_at();create trigger store_pages_updated before update on public.store_pages for each row execute function public.set_updated_at();
alter table public.store_generation_runs enable row level security;alter table public.stores enable row level security;alter table public.store_sections enable row level security;alter table public.store_pages enable row level security;
create policy store_runs_member_read on public.store_generation_runs for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=store_generation_runs.organization_id and m.user_id=auth.uid()));
create policy stores_member_read on public.stores for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=stores.organization_id and m.user_id=auth.uid()));
create policy store_sections_member_read on public.store_sections for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=store_sections.organization_id and m.user_id=auth.uid()));
create policy store_pages_member_read on public.store_pages for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=store_pages.organization_id and m.user_id=auth.uid()));
revoke all on table public.store_generation_runs,public.stores,public.store_sections,public.store_pages from anon,authenticated;grant select on table public.store_generation_runs,public.stores,public.store_sections,public.store_pages to authenticated;

create function public.start_store_generation(p_business_id uuid,p_provider text,p_model text,p_preferences jsonb default'{}')returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;p uuid;r uuid;j uuid;begin if u is null then raise exception'Authentication required'using errcode='42501';end if;select organization_id into o from public.businesses where id=p_business_id;if o is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Business not found'using errcode='42501';end if;select id into p from public.product_opportunities where business_id=p_business_id and organization_id=o and status='selected';select id into b from public.brand_directions where business_id=p_business_id and organization_id=o and selected_product_id=p and status='approved';if p is null or b is null then raise exception'Approved brand and selected product required'using errcode='22023';end if;if exists(select 1 from public.stores where business_id=p_business_id)then raise exception'A store already exists'using errcode='23505';end if;insert into public.store_generation_runs(organization_id,business_id,approved_brand_id,selected_product_id,status,provider,model,preferences,started_at)values(o,p_business_id,b,p,'running',p_provider,pg_catalog.btrim(p_model),coalesce(p_preferences,'{}'),pg_catalog.now())returning id into r;insert into public.ai_jobs(organization_id,business_id,job_type,status,input,started_at)values(o,p_business_id,'store_generation','running',pg_catalog.jsonb_build_object('storeGenerationRunId',r,'approvedBrandId',b,'selectedProductId',p,'provider',p_provider,'model',p_model),pg_catalog.now())returning id into j;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_generation_started','store_generation_run',r);return pg_catalog.jsonb_build_object('run_id',r,'job_id',j,'approved_brand_id',b,'selected_product_id',p);end$$;
create function public.complete_store_generation(p_run_id uuid,p_job_id uuid,p_store jsonb,p_sections jsonb,p_pages jsonb,p_input_tokens integer,p_output_tokens integer,p_total_tokens integer)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;a uuid;p uuid;s uuid;base text;candidate text;n integer:=1;sec jsonb;pg jsonb;begin if u is null then raise exception'Authentication required'using errcode='42501';end if;select organization_id,business_id,approved_brand_id,selected_product_id into o,b,a,p from public.store_generation_runs where id=p_run_id and status='running'for update;if b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Running store generation not found'using errcode='42501';end if;if not exists(select 1 from public.ai_jobs where id=p_job_id and organization_id=o and business_id=b and job_type='store_generation'and status='running'and input->>'storeGenerationRunId'=p_run_id::text)then raise exception'Running AI job not found'using errcode='22023';end if;if jsonb_typeof(p_store)<>'object'or jsonb_typeof(p_sections)<>'array'or jsonb_array_length(p_sections)<3 or jsonb_typeof(p_pages)<>'array'or jsonb_array_length(p_pages)<9 or p_store::text~'<[/]?[A-Za-z][^>]*>'or p_sections::text~'<[/]?[A-Za-z][^>]*>'or p_pages::text~'<[/]?[A-Za-z][^>]*>'or p_store->'theme'->>'primaryColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'secondaryColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'accentColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'backgroundColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'surfaceColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'textColor'!~'^#[0-9A-Fa-f]{6}$'or p_store->'theme'->>'mutedTextColor'!~'^#[0-9A-Fa-f]{6}$'then raise exception'Invalid structured store payload'using errcode='22023';end if;base=left(lower(regexp_replace(coalesce(p_store->>'slug','store'),'[^a-z0-9]+','-','g')),58);base=trim(both'-'from base);if base=''then base='store';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(base)::bigint);candidate=base;while exists(select 1 from public.stores where slug=candidate)loop n=n+1;candidate=base||'-'||n;end loop;insert into public.stores(organization_id,business_id,approved_brand_id,selected_product_id,generation_run_id,name,slug,status,theme,navigation,footer,seo_defaults)values(o,b,a,p,p_run_id,p_store->>'name',candidate,'generated',p_store->'theme',p_store->'navigation',p_store->'footer',p_store->'seo_defaults')returning id into s;for sec in select value from jsonb_array_elements(p_sections)loop insert into public.store_sections(organization_id,business_id,store_id,section_type,position,content,settings,is_enabled)values(o,b,s,(sec->>'section_type')::public.store_section_type,(sec->>'position')::integer,sec->'content',coalesce(sec->'settings','{}'),coalesce((sec->>'is_enabled')::boolean,true));end loop;for pg in select value from jsonb_array_elements(p_pages)loop insert into public.store_pages(organization_id,business_id,store_id,page_type,slug,title,seo_title,seo_description,content)values(o,b,s,(pg->>'page_type')::public.store_page_type,pg->>'slug',pg->>'title',pg->>'seo_title',pg->>'seo_description',pg->'content');end loop;if not exists(select 1 from public.store_sections where store_id=s and section_type='hero'and is_enabled)or not exists(select 1 from public.store_sections where store_id=s and section_type='featured_product'and is_enabled)or not exists(select 1 from public.store_sections where store_id=s and section_type='footer'and is_enabled)then raise exception'Required sections missing'using errcode='22023';end if;update public.store_generation_runs set status='completed',completed_at=now()where id=p_run_id;update public.ai_jobs set status='completed',completed_at=now(),output=jsonb_build_object('storeId',s,'storeGenerationRunId',p_run_id)where id=p_job_id;insert into public.usage_records(organization_id,user_id,usage_type,quantity,metadata)values(o,u,'store_generation',p_total_tokens,jsonb_build_object('provider',(select provider from public.store_generation_runs where id=p_run_id),'model',(select model from public.store_generation_runs where id=p_run_id),'input_tokens',p_input_tokens,'output_tokens',p_output_tokens,'total_tokens',p_total_tokens,'store_generation_run_id',p_run_id,'store_id',s));insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_generation_completed','store',s);return s;end$$;
create function public.fail_store_generation(p_run_id uuid,p_job_id uuid,p_error text)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin if u is null then raise exception'Authentication required'using errcode='42501';end if;select organization_id,business_id into o,b from public.store_generation_runs where id=p_run_id and status='running'for update;if b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Running store generation not found'using errcode='42501';end if;if not exists(select 1 from public.ai_jobs where id=p_job_id and organization_id=o and business_id=b and job_type='store_generation'and status='running'and input->>'storeGenerationRunId'=p_run_id::text)then raise exception'Running AI job not found'using errcode='22023';end if;update public.store_generation_runs set status='failed',error=left(coalesce(p_error,'Unknown store generation failure'),2000),completed_at=now()where id=p_run_id;update public.ai_jobs set status='failed',error=left(coalesce(p_error,'Unknown store generation failure'),2000),completed_at=now()where id=p_job_id and organization_id=o and business_id=b and job_type='store_generation'and status='running'and input->>'storeGenerationRunId'=p_run_id::text;return b;end$$;

create function public.update_store_theme(p_store_id uuid,p_theme jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin select organization_id,business_id into o,b from public.stores where id=p_store_id and status='generated'for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Store not found'using errcode='42501';end if;if jsonb_typeof(p_theme)<>'object'or(p_theme-array['primaryColor','secondaryColor','accentColor','backgroundColor','surfaceColor','textColor','mutedTextColor','headingFontDirection','bodyFontDirection','borderRadius','buttonStyle','cardStyle','spacingDensity'])<>'{}'::jsonb or p_theme->>'primaryColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'secondaryColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'accentColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'backgroundColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'surfaceColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'textColor'!~'^#[0-9A-Fa-f]{6}$'or p_theme->>'mutedTextColor'!~'^#[0-9A-Fa-f]{6}$'then raise exception'Invalid theme'using errcode='22023';end if;update public.stores set theme=p_theme where id=p_store_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_theme_updated','store',p_store_id);return b;end$$;
create function public.update_store_section(p_store_id uuid,p_section_id uuid,p_content jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin select s.organization_id,s.business_id into o,b from public.store_sections s join public.stores t on t.id=s.store_id and t.status='generated'where s.id=p_section_id and s.store_id=p_store_id for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)or jsonb_typeof(p_content)<>'object'or(p_content-array['headline','body'])<>'{}'::jsonb or p_content::text~'<[/]?[A-Za-z][^>]*>'then raise exception'Section not found or invalid'using errcode='42501';end if;update public.store_sections set content=content||p_content where id=p_section_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_section_updated','store_section',p_section_id);return b;end$$;
create function public.reorder_store_sections(p_store_id uuid,p_section_id uuid,p_direction text)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;pos int;other uuid;otherpos int;begin select s.organization_id,s.business_id,s.position into o,b,pos from public.store_sections s join public.stores t on t.id=s.store_id and t.status='generated'where s.id=p_section_id and s.store_id=p_store_id for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)or p_direction not in('up','down')then raise exception'Section not found'using errcode='42501';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_store_id::text)::bigint);select id,position into other,otherpos from public.store_sections where store_id=p_store_id and((p_direction='up'and position<pos)or(p_direction='down'and position>pos))order by case when p_direction='up'then-position else position end limit 1 for update;if other is not null then set constraints public.store_sections_position_unique deferred;update public.store_sections set position=case when id=p_section_id then otherpos else pos end where id in(p_section_id,other);end if;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_section_reordered','store_section',p_section_id);return b;end$$;
create function public.toggle_store_section(p_store_id uuid,p_section_id uuid,p_enabled boolean)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;t public.store_section_type;begin select s.organization_id,s.business_id,s.section_type into o,b,t from public.store_sections s join public.stores x on x.id=s.store_id and x.status='generated'where s.id=p_section_id and s.store_id=p_store_id for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Section not found'using errcode='42501';end if;if not p_enabled and t in('hero','featured_product','footer')then raise exception'Required section cannot be disabled'using errcode='22023';end if;update public.store_sections set is_enabled=p_enabled where id=p_section_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_section_toggled','store_section',p_section_id);return b;end$$;
create function public.update_store_page(p_store_id uuid,p_page_id uuid,p_title text,p_seo_title text,p_seo_description text,p_content jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin select p.organization_id,p.business_id into o,b from public.store_pages p join public.stores s on s.id=p.store_id and s.status='generated'where p.id=p_page_id and p.store_id=p_store_id for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)or jsonb_typeof(p_content)<>'object'or(p_content-array['body'])<>'{}'::jsonb or p_content::text~'<[/]?[A-Za-z][^>]*>'then raise exception'Page not found'using errcode='42501';end if;update public.store_pages set title=btrim(p_title),seo_title=btrim(p_seo_title),seo_description=btrim(p_seo_description),content=content||p_content where id=p_page_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_page_updated','store_page',p_page_id);return b;end$$;
create function public.store_is_publishable(p_store_id uuid)returns boolean language sql stable set search_path='' as $$select exists(select 1 from public.stores s join public.store_generation_runs r on r.id=s.generation_run_id and r.organization_id=s.organization_id and r.business_id=s.business_id and r.status='completed' join public.brand_directions b on b.id=s.approved_brand_id and b.organization_id=s.organization_id and b.business_id=s.business_id and b.selected_product_id=s.selected_product_id and b.status='approved' join public.product_opportunities p on p.id=s.selected_product_id and p.organization_id=s.organization_id and p.business_id=s.business_id and p.status='selected' where s.id=p_store_id and s.theme->>'primaryColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'secondaryColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'accentColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'backgroundColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'surfaceColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'textColor'~'^#[0-9A-Fa-f]{6}$'and s.theme->>'mutedTextColor'~'^#[0-9A-Fa-f]{6}$'and(select count(*)from public.store_sections x where x.store_id=s.id and x.section_type in('hero','featured_product','footer')and x.is_enabled)=3 and(select count(distinct page_type)from public.store_pages x where x.store_id=s.id)=9 and(select count(*)from public.store_pages x where x.store_id=s.id and x.page_type in('shipping','returns','privacy','terms')and x.content->>'isDraft'='true'and x.content->>'requiresReview'='true'and x.content->>'notice'='Draft policy. Review before publishing.')=4 and not exists(select 1 from public.store_sections x where x.store_id=s.id and x.section_type='testimonials'and x.is_enabled and(jsonb_typeof(x.content->'items')<>'array'or exists(select 1 from jsonb_array_elements(x.content->'items')i where i->>'placeholder'<>'true'))))$$;revoke all on function public.store_is_publishable(uuid)from public,anon,authenticated;
create function public.approve_store(p_store_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin select organization_id,business_id into o,b from public.stores where id=p_store_id and status='generated'for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Generated store not found'using errcode='42501';end if;if not public.store_is_publishable(p_store_id)then raise exception'Store validation failed'using errcode='22023';end if;if not exists(select 1 from public.store_sections where store_id=p_store_id and section_type='hero'and is_enabled)or not exists(select 1 from public.store_sections where store_id=p_store_id and section_type='featured_product'and is_enabled)or not exists(select 1 from public.store_sections where store_id=p_store_id and section_type='footer'and is_enabled)or(select count(distinct page_type)from public.store_pages where store_id=p_store_id)<9 then raise exception'Required store content missing'using errcode='22023';end if;update public.stores set status='approved',approved_at=now()where id=p_store_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_approved','store',p_store_id);return b;end$$;
create function public.publish_store(p_store_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();o uuid;b uuid;begin select organization_id,business_id into o,b from public.stores where id=p_store_id and status='approved'for update;if u is null or b is null or not exists(select 1 from public.organization_members where organization_id=o and user_id=u)then raise exception'Approved store not found'using errcode='42501';end if;if not public.store_is_publishable(p_store_id)then raise exception'Store validation failed'using errcode='22023';end if;update public.stores set status='published'where id=p_store_id;insert into public.audit_logs(organization_id,user_id,action,entity_type,entity_id)values(o,u,'store_published','store',p_store_id);return b;end$$;
create function public.get_public_store(p_slug text)returns jsonb language sql stable security definer set search_path='' as $$select pg_catalog.jsonb_build_object('store',pg_catalog.jsonb_build_object('name',s.name,'slug',s.slug,'status',s.status,'theme',s.theme,'navigation',s.navigation,'footer',s.footer,'seo_defaults',s.seo_defaults),'sections',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('section_type',x.section_type,'position',x.position,'content',pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('headline',x.content->'headline','body',x.content->'body','ctaLabel',x.content->'ctaLabel','ctaTarget',x.content->'ctaTarget','imagePrompt',x.content->'imagePrompt','price',x.content->'price','benefits',x.content->'benefits','items',x.content->'items','features',x.content->'features','useCases',x.content->'useCases','whoItIsFor',x.content->'whoItIsFor')),'is_enabled',x.is_enabled)order by x.position)from public.store_sections x where x.store_id=s.id and x.is_enabled),'[]'::jsonb),'pages',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('page_type',p.page_type,'slug',p.slug,'title',p.title,'seo_title',p.seo_title,'seo_description',p.seo_description,'content',pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('body',p.content->'body','price',p.content->'price','ctaLabel',p.content->'ctaLabel','isDraft',p.content->'isDraft','requiresReview',p.content->'requiresReview','notice',p.content->'notice'))))from public.store_pages p where p.store_id=s.id),'[]'::jsonb))from public.stores s where s.slug=p_slug and s.status='published'$$;
revoke all on function public.start_store_generation(uuid,text,text,jsonb),public.complete_store_generation(uuid,uuid,jsonb,jsonb,jsonb,integer,integer,integer),public.fail_store_generation(uuid,uuid,text),public.update_store_theme(uuid,jsonb),public.update_store_section(uuid,uuid,jsonb),public.reorder_store_sections(uuid,uuid,text),public.toggle_store_section(uuid,uuid,boolean),public.update_store_page(uuid,uuid,text,text,text,jsonb),public.approve_store(uuid),public.publish_store(uuid)from public,anon;
grant execute on function public.start_store_generation(uuid,text,text,jsonb),public.complete_store_generation(uuid,uuid,jsonb,jsonb,jsonb,integer,integer,integer),public.fail_store_generation(uuid,uuid,text),public.update_store_theme(uuid,jsonb),public.update_store_section(uuid,uuid,jsonb),public.reorder_store_sections(uuid,uuid,text),public.toggle_store_section(uuid,uuid,boolean),public.update_store_page(uuid,uuid,text,text,text,jsonb),public.approve_store(uuid),public.publish_store(uuid)to authenticated;
revoke all on function public.get_public_store(text)from public;grant execute on function public.get_public_store(text)to anon,authenticated;
commit;
